    quiz: [
      { question: "What practice change grew from Bowlby's work?", options: ["Separating children from parents in hospital", "Allowing parents to stay with young children in hospital", "Banning day care", "Sending children to boarding school early"], correct: 1, rationale: "Parents staying with children in hospital became standard. The other options go against his findings." },
      { question: "What is a key methodological weakness of the 44 thieves study?", options: ["It used too many children", "It was a randomised trial", "It was retrospective with a small, clinic-based sample", "It used only fathers"], correct: 2, rationale: "It was small and looked back in time. It was not large, not randomised and not about fathers." },
    ],
    tags: { topic: "attachment", difficulty: 2, objective: "Evaluate Bowlby's early attachment research", exams: ["cuet-pg", "ugc-net", "ma-semester"], module: "lifespan" },
